export function LessonList({ lessons, featured }) {
  // Pure: every step makes new arrays; lessons is untouched.
  const shown = [featured, ...lessons]
    .filter((l) => l.published)
    .toSorted((a, b) => a.order - b.order);

  return (
    <ul>
      {shown.map((l) => <li key={l.id}>{l.title}</li>)}
    </ul>
  );
}

// Impure version, for comparison: don't do this.
// lessons.push(featured);          mutates the parent's array.
// lessons.sort(byOrder);           sort changes it in place too.
// fetch("/api/log");               side effect on every render.
```

| During render | Belongs in |
|---|---|
| compute filtered or sorted copies. | render (pure). |
| change shared data. | nowhere; create new values instead. |
| respond to a click. | event handler. |
| sync with a server or timer. | effect (later module). |

